/**
 * Pure logic of the build report read from the `.map` file generated by z88dk.
 *
 * Depends on nothing but the standard library; `Z88dkReportService` reads the files and writes the output channel.
 */

export enum MapFileSymbols {
  CRT_ORG_CODE = 'CRT_ORG_CODE',
  __code_compiler_size = '__code_compiler_size',
  __data_compiler_size = '__data_compiler_size',
  __rodata_compiler_size = '__rodata_compiler_size',
  __bss_compiler_size = '__bss_compiler_size',
  __code_user_size = '__code_user_size',
  __data_user_size = '__data_user_size',
  __rodata_user_size = '__rodata_user_size',
  __bss_user_size = '__bss_user_size',
  __BSS_END_tail = '__BSS_END_tail',
  __register_sp = '__register_sp',
  CRT_MAX_HEAP_ADDRESS = 'CRT_MAX_HEAP_ADDRESS',
  __crt_stack_size = '__crt_stack_size',
}

export type MapFileSymbolValues = Partial<Record<MapFileSymbols, number>>;

export interface MapFileReport {
  startAddress?: number;
  compilerCodeSize?: number;
  compilerDataSize?: number;
  compilerRoDataSize?: number;
  compilerBssSize?: number;
  userCodeSize?: number;
  userDataSize?: number;
  userRoDataSize?: number;
  userBssSize?: number;
  totalCompiledCode?: number;
  topStack?: number;
  stackSize?: number;
  heapStart?: number;
  usedMemory?: number;
  freeMemory?: number;
}

// a stack symbol above 32 bits is treated as invalid
const MAX_SYMBOL_VALUE = 0xffffffff;
const REPORT_DESCRIPTION_WIDTH = 50;

/** Values of the known symbols (`NAME = $HEX` lines) in the content of a `.map` file. */
export function parseMapFileSymbols(mapFileContent: string): MapFileSymbolValues {
  const symbols: MapFileSymbolValues = {};
  const knownSymbols: string[] = Object.values(MapFileSymbols);
  const mapFileRegexp = /^(?<name>[A-Za-z0-9_]+)\s+=\s+\$(?<hex>[0-9A-Fa-f]+)/;

  for (const line of mapFileContent.split(/\r?\n/)) {
    const match = mapFileRegexp.exec(line);
    const name = match?.groups?.name;
    const hex = match?.groups?.hex;

    if (name !== undefined && hex !== undefined && knownSymbols.includes(name)) {
      symbols[name as MapFileSymbols] = parseInt(hex, 16);
    }
  }

  return symbols;
}

/** Memory layout of the program computed from the `.map` symbols; a value is `undefined` when a symbol it needs is missing. */
export function createMapFileReport(symbols: MapFileSymbolValues): MapFileReport {
  const startAddress = symbols[MapFileSymbols.CRT_ORG_CODE];
  const bssEndTail = symbols[MapFileSymbols.__BSS_END_tail];

  // if stack size is invalid, set to undefined
  let stackSize = symbols[MapFileSymbols.__crt_stack_size];
  if (stackSize === undefined || stackSize > MAX_SYMBOL_VALUE) {
    stackSize = undefined;
  }

  // Stack pointer register or max heap address if not found or invalid value
  let registerSp = symbols[MapFileSymbols.__register_sp];
  if (registerSp === undefined || registerSp > MAX_SYMBOL_VALUE) {
    registerSp = symbols[MapFileSymbols.CRT_MAX_HEAP_ADDRESS];
  }

  const sectionSizes = [
    symbols[MapFileSymbols.__code_compiler_size],
    symbols[MapFileSymbols.__data_compiler_size],
    symbols[MapFileSymbols.__rodata_compiler_size],
    symbols[MapFileSymbols.__bss_compiler_size],
    symbols[MapFileSymbols.__code_user_size],
    symbols[MapFileSymbols.__data_user_size],
    symbols[MapFileSymbols.__rodata_user_size],
    symbols[MapFileSymbols.__bss_user_size],
  ];

  return {
    startAddress: startAddress,

    compilerCodeSize: symbols[MapFileSymbols.__code_compiler_size],
    compilerDataSize: symbols[MapFileSymbols.__data_compiler_size],
    compilerRoDataSize: symbols[MapFileSymbols.__rodata_compiler_size],
    compilerBssSize: symbols[MapFileSymbols.__bss_compiler_size],

    userCodeSize: symbols[MapFileSymbols.__code_user_size],
    userDataSize: symbols[MapFileSymbols.__data_user_size],
    userRoDataSize: symbols[MapFileSymbols.__rodata_user_size],
    userBssSize: symbols[MapFileSymbols.__bss_user_size],

    totalCompiledCode: sectionSizes.every((size): size is number => size !== undefined)
      ? sectionSizes.reduce((total, size) => total + size, 0)
      : undefined,

    topStack: registerSp,
    stackSize: stackSize,
    heapStart: bssEndTail,

    // Bytes occupied from start (CRT_ORG_CODE) to BSS_END (heap start)
    usedMemory: startAddress !== undefined && bssEndTail !== undefined ? bssEndTail - startAddress : undefined,
    // Bytes free between BSS_END (heap start) and the top of the stack
    freeMemory: registerSp !== undefined && bssEndTail !== undefined ? registerSp - bssEndTail : undefined,
  };
}

/** One report line: the description padded to 50 characters, then the value in bytes (decimal and hexadecimal) or `N/A`. */
export function formatReportLine(description: string, value: number | undefined): string {
  const formattedValue = value || value == 0 ? `${value} (0x${value.toString(16).toUpperCase()}) bytes` : 'N/A';
  const padding = ' '.repeat(REPORT_DESCRIPTION_WIDTH - description.length);
  return `${description}${padding}${formattedValue}`;
}

/** Name of the build output (`EXEC_OUTPUT` in the Makefile), which names the `.map` file. */
export function findExecOutputName(makefileContent: string | undefined): string | undefined {
  const match = makefileContent?.match(/^EXEC_OUTPUT\s*=\s*([\w-]+)/m);
  return match ? match[1] : undefined;
}
